export declare const overlaysStyles = "\n/* ---- \u4E8C\u6B21\u786E\u8BA4\u5F39\u5C42 ---- */\n.wf-confirm-backdrop {\n  position: absolute;\n  z-index: 40;\n  inset: 0;\n  display: grid;\n  place-items: center;\n  padding: 20px;\n  background: color-mix(in srgb, var(--wf-bg) 72%, transparent);\n  backdrop-filter: blur(4px);\n}\n\n.wf-confirm {\n  width: min(540px, 100%);\n  max-height: calc(100vh - 40px);\n  overflow: auto;\n  padding: 18px;\n  border: 1px solid var(--wf-border-strong);\n  border-radius: 14px;\n  background: var(--wf-layer);\n  box-shadow: 0 20px 60px color-mix(in srgb, var(--wf-ink) 18%, transparent);\n}\n\n.wf-confirm h3 {\n  margin: 0 0 8px;\n  font-size: 15px;\n  color: var(--wf-ink);\n}\n\n.wf-confirm p {\n  margin: 0;\n  color: var(--wf-ink-2);\n  font-size: 12px;\n  line-height: 1.65;\n  white-space: pre-wrap;\n}\n\n.wf-confirm__actions {\n  display: flex;\n  justify-content: flex-end;\n  gap: 8px;\n  margin-top: 16px;\n  flex-wrap: wrap;\n}\n\n/* ---- \u8FD0\u884C\u5386\u53F2\u5F39\u5C42 ---- */\n.wf-history-backdrop {\n  position: absolute;\n  z-index: 30;\n  inset: 0;\n  display: grid;\n  place-items: center;\n  padding: 20px;\n  background: color-mix(in srgb, var(--wf-bg) 72%, transparent);\n  backdrop-filter: blur(4px);\n}\n\n.wf-history {\n  width: min(760px, 100%);\n  max-height: calc(100vh - 40px);\n  display: flex;\n  flex-direction: column;\n  padding: 18px;\n  border: 1px solid var(--wf-border-strong);\n  border-radius: 14px;\n  background: var(--wf-layer);\n  box-shadow: 0 20px 60px color-mix(in srgb, var(--wf-ink) 18%, transparent);\n}\n\n.wf-history h3 {\n  margin: 0 0 10px;\n  font-size: 15px;\n  color: var(--wf-ink);\n}\n\n.wf-history__list {\n  min-height: 0;\n  overflow: auto;\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  scrollbar-width: thin;\n}\n\n.wf-history__item {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  text-align: left;\n  border: 1px solid var(--wf-border);\n  border-radius: 10px;\n  background: var(--wf-layer-2);\n  padding: 9px 11px;\n  cursor: pointer;\n}\n\n.wf-history__item:hover {\n  border-color: var(--wf-brand);\n}\n\n.wf-history__item.is-active {\n  border-color: var(--wf-brand);\n  background: color-mix(in srgb, var(--wf-brand) 8%, var(--wf-layer-2));\n}\n\n.wf-history__title {\n  font-size: 12px;\n  font-weight: 650;\n  color: var(--wf-ink);\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.wf-history__chain {\n  font-size: 9px;\n  color: var(--wf-ink-2);\n  border: 1px solid var(--wf-border);\n  border-radius: 999px;\n  padding: 0 6px;\n}\n\n.wf-history__meta {\n  font: 9px/1.4 ui-monospace, SFMono-Regular, Menlo, monospace;\n  color: var(--wf-ink-2);\n}\n\n.wf-history__resume {\n  align-self: flex-end;\n}\n\n.wf-history__actions {\n  display: flex;\n  justify-content: flex-end;\n  gap: 8px;\n  margin-top: 12px;\n}\n\n/* ---- \u72B6\u6001\u5706\u70B9\uFF08\u8FD0\u884C / \u6210\u529F / \u5931\u8D25 / \u6682\u505C / \u8DF3\u8FC7 \u2026\uFF09 ---- */\n.wf-status-dot {\n  display: inline-block;\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  margin-right: 5px;\n  background: var(--wf-ink-2);\n}\n\n.wf-status-dot.is-running {\n  background: var(--wf-ok);\n  box-shadow: 0 0 0 3px color-mix(in srgb, var(--wf-ok) 18%, transparent);\n}\n\n.wf-status-dot.is-ok {\n  background: var(--wf-ok);\n}\n\n.wf-status-dot.is-fail {\n  background: var(--wf-err);\n}\n\n.wf-status-dot.is-armed {\n  background: var(--wf-warn);\n  box-shadow: 0 0 0 3px color-mix(in srgb, var(--wf-warn) 16%, transparent);\n}\n\n.wf-status-dot.is-pending {\n  background: var(--wf-ink-2);\n}\n\n.wf-status-dot.is-skipped {\n  background: var(--wf-ink-2);\n  opacity: .6;\n}\n\n.wf-status-dot.is-react-capped {\n  background: var(--wf-context);\n}\n\n.wf-status-dot.is-paused,\n.wf-status-dot.is-interrupted {\n  background: var(--wf-warn);\n}\n\n/* ---- \u5BFC\u5165\u9690\u85CF\u8F93\u5165\u4E0E\u9876\u90E8\u63D0\u793A ---- */\n.wf-import-hidden {\n  display: none;\n}\n\n.wf-toast-host {\n  position: fixed;\n  z-index: 9999;\n  top: 56px;\n  right: 16px;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  pointer-events: none;\n}\n\n.wf-toast {\n  pointer-events: auto;\n  display: flex;\n  align-items: flex-start;\n  gap: 8px;\n  min-width: 190px;\n  max-width: 330px;\n  padding: 9px 12px;\n  border-radius: 10px;\n  font-size: 12px;\n  line-height: 1.5;\n  box-shadow: 0 12px 32px color-mix(in srgb, var(--wf-ink) 22%, transparent);\n  animation: wf-toast-in .18s ease;\n}\n\n.wf-toast.is-success {\n  background: color-mix(in srgb, var(--wf-ok) 16%, var(--wf-layer));\n  border: 1px solid color-mix(in srgb, var(--wf-ok) 55%, var(--wf-border-strong));\n  color: var(--wf-ink);\n}\n\n.wf-toast.is-error {\n  background: color-mix(in srgb, var(--wf-err) 14%, var(--wf-layer));\n  border: 1px solid color-mix(in srgb, var(--wf-err) 55%, var(--wf-border-strong));\n  color: var(--wf-ink);\n}\n\n.wf-toast.is-info {\n  background: var(--wf-layer);\n  border: 1px solid var(--wf-border-strong);\n  color: var(--wf-ink);\n}\n\n.wf-toast__dot {\n  flex: none;\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n  margin-top: 5px;\n}\n\n.wf-toast.is-success .wf-toast__dot {\n  background: var(--wf-ok);\n}\n\n.wf-toast.is-error .wf-toast__dot {\n  background: var(--wf-err);\n}\n\n.wf-toast.is-info .wf-toast__dot {\n  background: var(--wf-brand);\n}\n\n@keyframes wf-toast-in {\n  from {\n    opacity: 0;\n    transform: translateY(-6px);\n  }\n\n  to {\n    opacity: 1;\n    transform: none;\n  }\n}\n";
